#!/usr/bin/env python3
"""Backport LVGL PR 10657 cache handoff/serialization to pinned 9.5.0.
Upstream: https://github.com/lvgl/lvgl/pull/10657
Image drawing remains disabled by PrinterHMI's trial configuration.
"""
from pathlib import Path
import hashlib
import sys

FILES = {'src/draw/espressif/ppa/lv_draw_ppa.c': ('4107ec94cfb6d83833e99832d1eac8210a00b57482ae58c55444b7ff4269daa1', 'e7deb0e29c2fb86ad59044ce14530d36e0c99412729787f628508b334b19ac02', '/**\n * @file lv_draw_ppa.c\n *\n */\n\n/*********************\n*      INCLUDES\n*********************/\n\n#include "lv_draw_ppa_private.h"\n#include "lv_draw_ppa.h"\n\n#if LV_USE_PPA\n\n/*********************\n*      DEFINES\n*********************/\n\n#define DRAW_UNIT_ID_PPA         80\n#define DRAW_UNIT_PPA_PREF_SCORE 70\n\n/**********************\n*  STATIC PROTOTYPES\n**********************/\n\nstatic int32_t ppa_evaluate(lv_draw_unit_t * draw_unit, lv_draw_task_t * task);\nstatic int32_t ppa_dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer);\nstatic bool other_unit_busy(const lv_layer_t * layer, const lv_draw_unit_t * self);\nstatic int32_t ppa_delete(lv_draw_unit_t * draw_unit);\nstatic void  ppa_execute_drawing(lv_draw_ppa_unit_t * u);\n\n/**********************\n*   GLOBAL FUNCTIONS\n**********************/\n\nvoid lv_draw_ppa_init(void)\n{\n    esp_err_t res;\n    ppa_client_config_t cfg = {0};\n\n    /* Create draw unit */\n    lv_draw_buf_ppa_init_handlers();\n    lv_draw_ppa_unit_t * draw_ppa_unit = lv_draw_create_unit(sizeof(lv_draw_ppa_unit_t));\n    draw_ppa_unit->base_unit.evaluate_cb = ppa_evaluate;\n    draw_ppa_unit->base_unit.dispatch_cb  = ppa_dispatch;\n    draw_ppa_unit->base_unit.delete_cb    = ppa_delete;\n    draw_ppa_unit->base_unit.name         = "ESP_PPA";\n\n    /* Register SRM client */\n    cfg.oper_type = PPA_OPERATION_SRM;\n    cfg.max_pending_trans_num = 1;\n#if (LV_PPA_BURST_LENGTH == 128)\n    cfg.data_burst_length = PPA_DATA_BURST_LENGTH_128;\n#elif (LV_PPA_BURST_LENGTH == 64)\n    cfg.data_burst_length = PPA_DATA_BURST_LENGTH_64;\n#elif (LV_PPA_BURST_LENGTH == 32)\n    cfg.data_burst_length = PPA_DATA_BURST_LENGTH_32;\n#elif (LV_PPA_BURST_LENGTH == 16)\n    cfg.data_burst_length = PPA_DATA_BURST_LENGTH_16;\n#elif (LV_PPA_BURST_LENGTH == 8)\n    cfg.data_burst_length = PPA_DATA_BURST_LENGTH_8;\n#else\n#error "Invalid burst length selection for PPA"\n#endif\n\n    res = ppa_register_client(&cfg, &draw_ppa_unit->srm_client);\n    LV_ASSERT(res == ESP_OK);\n\n    /* Register Fill client */\n    cfg.oper_type = PPA_OPERATION_FILL;\n    res = ppa_register_client(&cfg, &draw_ppa_unit->fill_client);\n    LV_ASSERT(res == ESP_OK);\n\n    /* Register Blend client */\n    cfg.oper_type = PPA_OPERATION_BLEND;\n\n    res = ppa_register_client(&cfg, &draw_ppa_unit->blend_client);\n    LV_ASSERT(res == ESP_OK);\n}\n\nvoid lv_draw_ppa_deinit(void)\n{\n    /* No global deinit required */\n}\n\n/**********************\n*   STATIC FUNCTIONS\n**********************/\nstatic int32_t ppa_evaluate(lv_draw_unit_t * u, lv_draw_task_t * t)\n{\n    LV_UNUSED(u);\n    const lv_draw_dsc_base_t * base = (lv_draw_dsc_base_t *)t->draw_dsc;\n\n    if(!ppa_dest_cf_supported(base->layer->color_format)) return 0;\n\n    switch(t->type) {\n        case LV_DRAW_TASK_TYPE_FILL: {\n                const lv_draw_fill_dsc_t * dsc = (lv_draw_fill_dsc_t *)t->draw_dsc;\n                if((dsc->radius != 0 || dsc->grad.dir != LV_GRAD_DIR_NONE)) return 0;\n                if(dsc->opa <= (lv_opa_t)LV_OPA_MAX) return 0;\n\n                if(t->preference_score > DRAW_UNIT_PPA_PREF_SCORE) {\n                    t->preference_score = DRAW_UNIT_PPA_PREF_SCORE;\n                    t->preferred_draw_unit_id = DRAW_UNIT_ID_PPA;\n                }\n                return 1;\n            }\n\n#if LV_USE_PPA_IMG\n        case LV_DRAW_TASK_TYPE_IMAGE: {\n                lv_draw_image_dsc_t * dsc = t->draw_dsc;\n                if(!(dsc->header.cf < LV_COLOR_FORMAT_PROPRIETARY_START\n                     && dsc->clip_radius == 0\n                     && dsc->bitmap_mask_src == NULL\n                     && dsc->sup == NULL\n                     && dsc->tile == 0\n                     && dsc->blend_mode == LV_BLEND_MODE_NORMAL\n                     && dsc->recolor_opa <= LV_OPA_MIN\n                     && dsc->opa <= (lv_opa_t)LV_OPA_MAX\n                     && dsc->skew_y == 0\n                     && dsc->skew_x == 0\n                     && dsc->scale_x == 256\n                     && dsc->scale_y == 256\n                     && dsc->rotation == 0\n                     && lv_image_src_get_type(dsc->src) == LV_IMAGE_SRC_VARIABLE\n                     && (dsc->header.cf == LV_COLOR_FORMAT_RGB888\n                         || dsc->header.cf == LV_COLOR_FORMAT_RGB565)\n                     && (dsc->base.layer->color_format == LV_COLOR_FORMAT_RGB888\n                         || dsc->base.layer->color_format == LV_COLOR_FORMAT_RGB565))) {\n                    return 0;\n                }\n\n                if(t->preference_score > DRAW_UNIT_PPA_PREF_SCORE) {\n                    t->preference_score = DRAW_UNIT_PPA_PREF_SCORE;\n                    t->preferred_draw_unit_id = DRAW_UNIT_ID_PPA;\n                }\n                return 1;\n            }\n#endif\n        default:\n            return 0;\n    }\n}\n\nstatic bool other_unit_busy(const lv_layer_t * layer, const lv_draw_unit_t * self)\n{\n    lv_draw_task_t * t = layer->draw_task_head;\n    while(t) {\n        if(t->state == LV_DRAW_TASK_STATE_IN_PROGRESS && t->draw_unit != self) return true;\n        t = t->next;\n    }\n    return false;\n}\n\nstatic int32_t ppa_dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer)\n{\n    lv_draw_ppa_unit_t * u = (lv_draw_ppa_unit_t *)draw_unit;\n    if(u->task_act) {\n        return LV_DRAW_UNIT_IDLE;\n    }\n\n    /* Row cache maintenance must not discard another unit\'s pixels. */\n    if(other_unit_busy(layer, draw_unit)) return LV_DRAW_UNIT_IDLE;\n\n    lv_draw_task_t * t = lv_draw_get_available_task(layer, NULL, DRAW_UNIT_ID_PPA);\n    if(!t || t->preferred_draw_unit_id != DRAW_UNIT_ID_PPA) return LV_DRAW_UNIT_IDLE;\n    if(lv_draw_layer_alloc_buf(layer) == NULL) return LV_DRAW_UNIT_IDLE;\n\n    t->state = LV_DRAW_TASK_STATE_IN_PROGRESS;\n    u->task_act = t;\n    u->task_act->draw_unit = draw_unit;\n\n    ppa_execute_drawing(u);\n\n    u->task_act->state = LV_DRAW_TASK_STATE_FINISHED;\n    u->task_act = NULL;\n    lv_draw_dispatch_request();\n\n    return 1;\n}\n\nstatic int32_t ppa_delete(lv_draw_unit_t * draw_unit)\n{\n    lv_draw_ppa_unit_t * u = (lv_draw_ppa_unit_t *)draw_unit;\n    ppa_unregister_client(u->srm_client);\n    ppa_unregister_client(u->fill_client);\n    ppa_unregister_client(u->blend_client);\n    return 0;\n}\n\nstatic void ppa_execute_drawing(lv_draw_ppa_unit_t * u)\n{\n    lv_draw_task_t * t         = u->task_act;\n    lv_layer_t * layer         = t->target_layer;\n    lv_draw_buf_t * buf        = layer->draw_buf;\n    lv_area_t area;\n\n    if(!lv_area_intersect(&area, &t->area, &t->clip_area)) return;\n    /* Cache handlers consume buffer-relative coordinates, not layer space. */\n    lv_area_t buf_area = area;\n    lv_area_move(&buf_area, -layer->buf_area.x1, -layer->buf_area.y1);\n    lv_draw_buf_flush_cache(buf, &buf_area);\n\n    switch(t->type) {\n        case LV_DRAW_TASK_TYPE_FILL:\n            lv_draw_ppa_fill(t, (lv_draw_fill_dsc_t *)t->draw_dsc, &area);\n            break;\n        case LV_DRAW_TASK_TYPE_IMAGE:\n            lv_draw_ppa_img(t, (lv_draw_image_dsc_t *)t->draw_dsc, &area);\n            break;\n        default:\n            return;\n    }\n    /* This pinned backend has no software fallback in its fill/image calls. */\n    lv_draw_buf_invalidate_cache(buf, &buf_area);\n}\n\n#endif /*LV_USE_PPA*/\n'), 'src/draw/espressif/ppa/lv_draw_ppa_buf.c': ('ea2298651f61076521ea53c77d0a3474f54126405949bd5c5a710eb2000fc7a4', 'c1c88647891e520236d406e42c1296911695627541990534d8bd7d9ceb1fa211', '/**\n * @file lv_draw_ppa_buf.c\n *\n */\n\n/*********************\n *      INCLUDES\n *********************/\n#include "lv_draw_ppa_private.h"\n#include "lv_draw_ppa.h"\n\n#if LV_USE_PPA\n#include LV_STDINT_INCLUDE\n#include "../../lv_draw_buf_private.h"\n\n/*********************\n *      DEFINES\n *********************/\n\n/**********************\n *      TYPEDEFS\n *********************/\n\n/**********************\n *  STATIC PROTOTYPES\n *********************/\nstatic void invalidate_cache(const lv_draw_buf_t * draw_buf, const lv_area_t * area);\nstatic void flush_cache(const lv_draw_buf_t * draw_buf, const lv_area_t * area);\nstatic void cache_msync_rows(const lv_draw_buf_t * draw_buf, const lv_area_t * area, uint32_t dir);\n\n/**********************\n *   GLOBAL FUNCTIONS\n *********************/\nvoid lv_draw_buf_ppa_init_handlers(void)\n{\n    lv_draw_buf_handlers_t * handlers = lv_draw_buf_get_handlers();\n    handlers->invalidate_cache_cb = invalidate_cache;\n    handlers->flush_cache_cb = flush_cache;\n}\n\n/**********************\n *   STATIC FUNCTIONS\n *********************/\n\nstatic void cache_msync_rows(const lv_draw_buf_t * draw_buf, const lv_area_t * area, uint32_t dir)\n{\n    size_t line = esp_cache_get_line_size_by_addr(draw_buf->data);\n    if(line == 0) return; /* Not cached */\n\n    size_t start = 0;\n    size_t end = draw_buf->data_size;\n\n    /* Whole rows, and the area is relative to the buffer */\n    if(area) {\n        uint32_t stride = draw_buf->header.stride;\n        int32_t y1 = area->y1 < 0 ? 0 : area->y1;\n        int32_t y2 = LV_MIN(area->y2, (int32_t)draw_buf->header.h - 1);\n        if(stride == 0 || y2 < y1) return;\n\n        start = (size_t)y1 * stride;\n        end = (size_t)(y2 + 1) * stride;\n    }\n\n    /* M2C is refused unless the range is whole cache lines */\n    start &= ~(line - 1);\n    end = (end + line - 1) & ~(line - 1);\n    if(end > draw_buf->data_size) end = draw_buf->data_size & ~(line - 1);\n    if(start >= end) return;\n\n    esp_cache_msync(draw_buf->data + start, end - start, dir | ESP_CACHE_MSYNC_FLAG_TYPE_DATA);\n}\n\nstatic void invalidate_cache(const lv_draw_buf_t * draw_buf, const lv_area_t * area)\n{\n    cache_msync_rows(draw_buf, area, ESP_CACHE_MSYNC_FLAG_DIR_M2C);\n}\n\nstatic void flush_cache(const lv_draw_buf_t * draw_buf, const lv_area_t * area)\n{\n    cache_msync_rows(draw_buf, area, ESP_CACHE_MSYNC_FLAG_DIR_C2M);\n}\n#endif /* LV_USE_PPA */\n')}

def apply(component):
    changes = []
    for relative, (before, after, replacement) in FILES.items():
        path = component / relative
        if path.is_symlink(): raise RuntimeError('Refusing symlinked PPA source: ' + relative)
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        if digest == after: continue
        if digest != before:
            raise RuntimeError(relative + ' differs from verified LVGL 9.5.0; no source changed')
        data = replacement.encode()
        if hashlib.sha256(data).hexdigest() != after: raise RuntimeError('Invalid PPA patch payload')
        changes.append((path, data))
    for path, data in changes: path.write_bytes(data)
    print('PASS: LVGL 9.5 PPA cache handoff/serialization correction ' + ('applied' if changes else 'already applied'))

if __name__ == '__main__':
    try:
        if len(sys.argv)>2: raise RuntimeError('Usage: apply_lvgl95_ppa_cache.py [lvgl-component-dir]')
        component=Path(sys.argv[1]) if len(sys.argv)==2 else Path(__file__).resolve().parents[1]/'managed_components/lvgl__lvgl'
        apply(component)
    except (OSError, RuntimeError) as error:
        raise SystemExit('ERROR: '+str(error))
